// Join src/*.js, the sample leads and apps-script/Code.gs into one file,
// dist/Code.gs, to paste into the Apps Script editor (Extensions > Apps Script).
//   npm run bundle
// Same file order as tests/load.js, so the tested code is the shipped code.
// Adapted from bilingual-sla-tracker (scripts/bundle.js); the SAMPLE_LEADS
// part is new (for the "Load sample data" menu item).
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { ROOT, SRC_DIR, srcFiles } from "../tests/load.js";
import { parseCsv } from "./csv.js";

export const DIST_FILE = path.join(ROOT, "dist", "Code.gs");

export function bundle() {
  const read = (file) => fs.readFileSync(file, "utf-8").replace(/\r\n/g, "\n").trimEnd() + "\n";
  const sample = parseCsv(read(path.join(ROOT, "data", "leads.csv")));
  const parts = [
    "// Puentara lead follow-up for Google Sheets (Puentara is a fictional demo company).\n" +
    "// GENERATED by scripts/bundle.js from src/*.js, data/leads.csv and apps-script/Code.gs.\n" +
    "// Do not edit this file: edit those files, then run `npm run bundle`.\n",
  ];
  for (const file of srcFiles()) {
    parts.push(`// ===== src/${file} =====\n` + read(path.join(SRC_DIR, file)));
  }
  parts.push("// ===== data/leads.csv (synthetic sample leads for \"Load sample data\") =====\n" +
    "var SAMPLE_LEADS = [\n" + sample.map((row) => "  " + JSON.stringify(row) + ",").join("\n") + "\n];\n");
  parts.push("// ===== apps-script/Code.gs =====\n" + read(path.join(ROOT, "apps-script", "Code.gs")));
  return parts.join("\n");
}

function main() {
  fs.mkdirSync(path.dirname(DIST_FILE), { recursive: true });
  const text = bundle();
  fs.writeFileSync(DIST_FILE, text, "utf-8");
  console.log(`Wrote dist/Code.gs (${text.split("\n").length - 1} lines). Paste it into Extensions > Apps Script, then reload the sheet.`);
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) main();
